//! Golden-fixture, causality, determinism, and edge-case tests for the
//! causal fill engine.
//!
//! The bar fixture is a checked-in CSV of synthetic candles, ATR values, and
//! the decision each bar produces. The fill fixture is hand-derived from the
//! program plan's execution policy: next-bar-open market fills, an ATR bracket
//! anchored at the entry fill price, stop-first ties, and fees and slippage on
//! every fill. Neither fixture is generated by the code under test.
//!
//! An empty cell is unavailable. Prices are compared with a tight tolerance so
//! the fixture can write decimal values instead of the exact binary expansion
//! of each computed float; determinism is asserted separately by comparing the
//! engine's own values across repeated runs.

use quantrule_backtest::execution::{
    ExecutionConfig, ExecutionEngine, Fill, FillReason, OrderIntent, OrderRecord, OrderSide,
    OrderState, RejectReason, Rejection, Trigger,
};
use quantrule_backtest::strategy::{
    Decision, Entry, Exit, ExitReason, RiskPolicy, Side, StrategyInput,
};
use quantrule_data::Candle;

fn intent(decision: Decision) -> OrderIntent {
    match decision {
        Decision::Hold => OrderIntent::Hold,
        Decision::Enter(entry) => OrderIntent::Enter {
            intent: entry.intent,
            bar_index: entry.bar.bar_index,
            open_time: entry.bar.open_time,
            max_notional: None,
        },
        Decision::Exit(exit) => OrderIntent::Exit {
            side: exit.side,
            bar_index: exit.bar.bar_index,
            open_time: exit.bar.open_time,
        },
    }
}

const BARS: &str = include_str!("fixtures/execution_fills_bars.csv");
const FILLS: &str = include_str!("fixtures/execution_fills_golden.csv");
const QUANTITIES: &str = include_str!("fixtures/execution_quantities.csv");
const BARS_HEADER: &str = "bar,timestamp,open,high,low,close,volume,atr14,decision";
const FILLS_HEADER: &str =
    "fill,bar,timestamp,side,quantity,reference_price,slippage,price,fee,reason";
const QUANTITIES_HEADER: &str =
    "entry_bar,quantity,fill_id,fill_bar,side,fill_quantity,fill_price,fill_fee";

const FEE_RATE: f64 = 0.001;
const SLIPPAGE_BPS: f64 = 2.0;
const QUANTITY: f64 = 1.0;

#[derive(Debug, Clone, Copy)]
struct BarRow {
    candle: Candle,
    atr14: Option<f64>,
    decision: Decision,
}

#[derive(Debug, Clone, Copy)]
struct FillRow {
    side: OrderSide,
    quantity: f64,
    reference_price: f64,
    slippage: f64,
    price: f64,
    fee: f64,
    bar: usize,
    time: i64,
    reason: FillReason,
}

#[derive(Debug, Clone, Copy)]
struct QuantityRow {
    entry_bar: usize,
    quantity: f64,
    fill_id: u64,
    fill_bar: usize,
    side: OrderSide,
    fill_quantity: f64,
    fill_price: f64,
    fill_fee: f64,
}

fn number(field: &str) -> Option<f64> {
    if field.is_empty() {
        None
    } else {
        Some(
            field
                .parse::<f64>()
                .unwrap_or_else(|error| panic!("invalid number {field:?}: {error}")),
        )
    }
}

fn parse<T>(field: &str) -> T
where
    T: std::str::FromStr,
    T::Err: std::fmt::Display,
{
    field
        .parse::<T>()
        .unwrap_or_else(|error| panic!("invalid value {field:?}: {error}"))
}

fn order_side(field: &str) -> OrderSide {
    match field {
        "buy" => OrderSide::Buy,
        "sell" => OrderSide::Sell,
        other => panic!("unknown order side {other:?}"),
    }
}

fn fill_reason(field: &str) -> FillReason {
    match field {
        "entry" => FillReason::Entry,
        "exit" => FillReason::Exit,
        "stop_loss" => FillReason::StopLoss,
        "take_profit" => FillReason::TakeProfit,
        other => panic!("unknown fill reason {other:?}"),
    }
}

fn decision(field: &str, bar: StrategyInput) -> Decision {
    match field {
        "hold" => Decision::Hold,
        "enter_long" => Decision::Enter(Entry {
            bar,
            intent: RiskPolicy::default().intent(Side::Long),
        }),
        "enter_short" => Decision::Enter(Entry {
            bar,
            intent: RiskPolicy::default().intent(Side::Short),
        }),
        "exit_long" => Decision::Exit(Exit {
            side: Side::Long,
            bar,
            reason: ExitReason::ContextLost,
        }),
        "exit_short" => Decision::Exit(Exit {
            side: Side::Short,
            bar,
            reason: ExitReason::ContextLost,
        }),
        other => panic!("unknown decision {other:?}"),
    }
}

fn load_bars() -> Vec<BarRow> {
    let mut lines = BARS.lines();
    assert_eq!(
        lines.next(),
        Some(BARS_HEADER),
        "bar fixture header changed"
    );

    let mut rows = Vec::new();
    for line in lines {
        let fields: Vec<&str> = line.split(',').collect();
        assert_eq!(fields.len(), 9, "wrong column count in {line:?}");

        let bar = parse::<usize>(fields[0]);
        assert_eq!(bar, rows.len(), "fixture bars must be contiguous");
        let time = parse::<i64>(fields[1]);
        let candle = Candle::new(
            bar as u64,
            time,
            parse::<f64>(fields[2]),
            parse::<f64>(fields[3]),
            parse::<f64>(fields[4]),
            parse::<f64>(fields[5]),
            number(fields[6]),
        )
        .unwrap_or_else(|error| panic!("invalid candle on bar {bar}: {error}"));

        let (direction, momentum, structure) = match fields[8] {
            "enter_long" => (Some(0.5), Some(0.5), Some(1.0)),
            "enter_short" => (Some(-0.5), Some(-0.5), Some(-1.0)),
            _ => (Some(0.0), Some(0.0), Some(0.0)),
        };
        let input = StrategyInput::new(900, bar, time, direction, momentum, structure);

        rows.push(BarRow {
            candle,
            atr14: number(fields[7]),
            decision: decision(fields[8], input),
        });
    }
    rows
}

fn load_fills() -> Vec<FillRow> {
    let mut lines = FILLS.lines();
    assert_eq!(
        lines.next(),
        Some(FILLS_HEADER),
        "fill fixture header changed"
    );

    let mut rows = Vec::new();
    for line in lines {
        let fields: Vec<&str> = line.split(',').collect();
        assert_eq!(fields.len(), 10, "wrong column count in {line:?}");
        let fill = parse::<usize>(fields[0]);
        assert_eq!(fill, rows.len(), "fixture fills must be contiguous");

        rows.push(FillRow {
            bar: parse::<usize>(fields[1]),
            time: parse::<i64>(fields[2]),
            side: order_side(fields[3]),
            quantity: parse::<f64>(fields[4]),
            reference_price: parse::<f64>(fields[5]),
            slippage: parse::<f64>(fields[6]),
            price: parse::<f64>(fields[7]),
            fee: parse::<f64>(fields[8]),
            reason: fill_reason(fields[9]),
        });
    }
    rows
}

fn load_quantities() -> Vec<QuantityRow> {
    let mut lines = QUANTITIES.lines();
    assert_eq!(
        lines.next(),
        Some(QUANTITIES_HEADER),
        "quantity fixture header changed"
    );

    let mut rows = Vec::new();
    for line in lines {
        let fields: Vec<&str> = line.split(',').collect();
        assert_eq!(fields.len(), 8, "wrong column count in {line:?}");
        rows.push(QuantityRow {
            entry_bar: parse::<usize>(fields[0]),
            quantity: parse::<f64>(fields[1]),
            fill_id: parse::<u64>(fields[2]),
            fill_bar: parse::<usize>(fields[3]),
            side: order_side(fields[4]),
            fill_quantity: parse::<f64>(fields[5]),
            fill_price: parse::<f64>(fields[6]),
            fill_fee: parse::<f64>(fields[7]),
        });
    }
    rows
}

fn engine() -> ExecutionEngine {
    ExecutionEngine::new(ExecutionConfig::new(FEE_RATE, SLIPPAGE_BPS).expect("the costs are valid"))
        .expect("the engine is valid")
}

fn run(rows: &[BarRow]) -> (Vec<Fill>, Vec<Rejection>, Vec<OrderRecord>) {
    let mut engine = engine();
    let mut fills = Vec::new();
    let mut rejections = Vec::new();
    let mut orders = Vec::new();
    for row in rows {
        let batch = engine
            .advance(&row.candle, true)
            .expect("the fixture bar is valid");
        fills.extend(batch.fills);
        rejections.extend(batch.rejections);
        orders.extend(batch.orders);
        let batch = engine
            .submit(intent(row.decision), Some(QUANTITY), row.atr14)
            .expect("the fixture decision is valid");
        rejections.extend(batch.rejections);
        orders.extend(batch.orders);
    }
    let batch = engine.finish();
    rejections.extend(batch.rejections);
    orders.extend(batch.orders);
    (fills, rejections, orders)
}

fn run_with_quantities(
    rows: &[BarRow],
    quantities: &[QuantityRow],
) -> (Vec<Fill>, Vec<Rejection>, Vec<OrderRecord>) {
    let mut engine = engine();
    let mut fills = Vec::new();
    let mut rejections = Vec::new();
    let mut orders = Vec::new();
    for row in rows {
        let quantity = match row.decision {
            Decision::Enter(entry) => Some(
                quantities
                    .iter()
                    .find(|row| row.entry_bar == entry.bar.bar_index)
                    .unwrap_or_else(|| {
                        panic!("no quantity fixture for entry bar {}", entry.bar.bar_index)
                    })
                    .quantity,
            ),
            Decision::Hold | Decision::Exit(_) => Some(QUANTITY),
        };
        let batch = engine
            .advance(&row.candle, true)
            .expect("the fixture bar is valid");
        fills.extend(batch.fills);
        rejections.extend(batch.rejections);
        orders.extend(batch.orders);
        let batch = engine
            .submit(intent(row.decision), quantity, row.atr14)
            .expect("the fixture decision is valid");
        rejections.extend(batch.rejections);
        orders.extend(batch.orders);
    }
    let batch = engine.finish();
    rejections.extend(batch.rejections);
    orders.extend(batch.orders);
    (fills, rejections, orders)
}

/// Collapses the record stream to one record per order, keeping the last.
fn last_record_per_order(orders: &[OrderRecord]) -> Vec<OrderRecord> {
    let mut resolved: Vec<OrderRecord> = Vec::new();
    for order in orders {
        if let Some(index) = resolved
            .iter()
            .position(|seen| seen.order_id == order.order_id)
        {
            resolved[index] = *order;
        } else {
            resolved.push(*order);
        }
    }
    resolved
}

/// The bar at which a record became knowable: the fill bar, else the
/// submission bar.
fn effective_bar(order: &OrderRecord) -> usize {
    order.filled_bar.unwrap_or(order.submitted_bar)
}

fn approx(actual: f64, expected: f64, field: &str, bar: usize) {
    assert!(
        (actual - expected).abs() < 1e-9,
        "bar {bar} {field}: expected {expected}, got {actual}"
    );
}

#[test]
fn the_engine_matches_the_golden_fill_fixture() {
    let bars = load_bars();
    assert_eq!(bars.len(), 8, "bar fixture row count changed");
    let expected = load_fills();
    assert_eq!(expected.len(), 4, "fill fixture row count changed");

    let (fills, rejections, orders) = run(&bars);
    assert!(
        rejections.is_empty(),
        "unexpected rejections: {rejections:?}"
    );
    assert_eq!(fills.len(), expected.len(), "fill count changed");

    for (fill, row) in fills.iter().zip(&expected) {
        assert_eq!(fill.side, row.side, "bar {} side", fill.bar);
        assert_eq!(fill.reason, row.reason, "bar {} reason", fill.bar);
        assert_eq!(fill.bar, row.bar, "fill bar");
        assert_eq!(fill.time, row.time, "bar {} time", fill.bar);
        approx(fill.quantity, row.quantity, "quantity", fill.bar);
        approx(
            fill.reference_price,
            row.reference_price,
            "reference_price",
            fill.bar,
        );
        approx(fill.slippage, row.slippage, "slippage", fill.bar);
        approx(fill.price, row.price, "price", fill.bar);
        approx(fill.fee, row.fee, "fee", fill.bar);
    }

    // A report keeps the last record per id: two pending records and four
    // resolved ones collapse to one record per order.
    let resolved = last_record_per_order(&orders);
    assert_eq!(resolved.len(), 4, "unique order count changed");
    for (order_id, order) in resolved.iter().enumerate() {
        assert_eq!(order.order_id, order_id as u64);
        assert_eq!(order.state, OrderState::Filled);
        assert_eq!(order.fill_id, Some(order_id as u64));
        assert_eq!(order.rejection_reason, None);
    }
    // The bracket orders became live when their entries filled.
    assert_eq!(resolved[1].submitted_bar, 1);
    assert_eq!(resolved[1].trigger, Trigger::Stop { price: 98.02 });
    assert_eq!(resolved[3].submitted_bar, 4);
}

#[test]
fn later_bars_do_not_change_earlier_fills() {
    let bars = load_bars();
    let prefix = 3;

    let (prefix_fills, _, _) = run(&bars[..prefix]);
    let (full_fills, _, _) = run(&bars);

    let prefix_early: Vec<Fill> = prefix_fills
        .iter()
        .copied()
        .filter(|fill| fill.bar < prefix)
        .collect();
    let full_early: Vec<Fill> = full_fills
        .iter()
        .copied()
        .filter(|fill| fill.bar < prefix)
        .collect();
    assert_eq!(prefix_early, full_early);

    let mut changed = bars.to_vec();
    changed[4].candle = Candle::new(4, 3600, 200.0, 200.5, 199.0, 200.0, Some(10.0))
        .expect("the changed candle is valid");
    let (changed_fills, _, _) = run(&changed);
    let changed_early: Vec<Fill> = changed_fills
        .iter()
        .copied()
        .filter(|fill| fill.bar < 4)
        .collect();
    let full_before_four: Vec<Fill> = full_fills
        .iter()
        .copied()
        .filter(|fill| fill.bar < 4)
        .collect();
    assert_eq!(changed_early, full_before_four);
}

#[test]
fn repeated_runs_are_identical() {
    let bars = load_bars();
    let expected = run(&bars);

    for _ in 0..10 {
        assert_eq!(run(&bars), expected);
    }
}

#[test]
fn an_empty_series_produces_no_fills_or_rejections() {
    let mut engine = engine();
    let batch = engine.finish();

    assert!(batch.is_empty());
    assert!(engine.position().is_flat());
}

#[test]
fn a_single_candle_cannot_fill_and_is_rejected_at_finish() {
    let bars = load_bars();
    let (fills, rejections, _) = run(&bars[..1]);

    assert!(fills.is_empty());
    assert_eq!(
        rejections,
        vec![Rejection {
            order_id: 0,
            bar: 0,
            time: 0,
            reason: RejectReason::NoNextBar,
        }]
    );
}

#[test]
fn a_series_that_never_fills_leaves_the_order_pending_until_finish() {
    let bars = [
        BarRow {
            candle: Candle::new(0, 0, 100.0, 101.0, 99.0, 100.0, Some(10.0))
                .expect("the candle is valid"),
            atr14: Some(1.0),
            decision: Decision::Hold,
        },
        BarRow {
            candle: Candle::new(1, 900, 100.0, 101.0, 99.5, 100.5, Some(10.0))
                .expect("the candle is valid"),
            atr14: Some(1.0),
            decision: Decision::Enter(Entry {
                bar: StrategyInput::new(900, 1, 900, Some(0.5), Some(0.5), Some(1.0)),
                intent: RiskPolicy::default().intent(Side::Long),
            }),
        },
    ];

    let (fills, rejections, _) = run(&bars);
    assert!(fills.is_empty());
    assert_eq!(
        rejections,
        vec![Rejection {
            order_id: 0,
            bar: 1,
            time: 900,
            reason: RejectReason::NoNextBar,
        }]
    );
}

#[test]
fn per_entry_quantities_reach_the_fills() {
    let bars = load_bars();
    let quantities = load_quantities();
    let (fills, rejections, orders) = run_with_quantities(&bars, &quantities);
    assert!(
        rejections.is_empty(),
        "unexpected rejections: {rejections:?}"
    );
    assert_eq!(fills.len(), quantities.len(), "fill count changed");

    for (fill, row) in fills.iter().zip(&quantities) {
        assert_eq!(fill.bar, row.fill_bar, "fill bar");
        assert_eq!(fill.side, row.side, "bar {} side", fill.bar);
        approx(fill.quantity, row.fill_quantity, "quantity", fill.bar);
        approx(fill.price, row.fill_price, "price", fill.bar);
        approx(fill.fee, row.fill_fee, "fee", fill.bar);
    }

    // A bracket fill carries its entry's quantity, and the order record that
    // carries the fill id agrees with the fixture.
    assert_eq!(fills[1].quantity, fills[0].quantity);
    assert_eq!(fills[3].quantity, fills[2].quantity);
    for row in &quantities {
        let order = orders
            .iter()
            .find(|order| order.fill_id == Some(row.fill_id))
            .unwrap_or_else(|| panic!("no order carries fill id {}", row.fill_id));
        assert_eq!(order.state, OrderState::Filled);
        assert_eq!(order.filled_bar, Some(row.fill_bar));
        match order.quantity {
            Some(quantity) => approx(quantity, row.fill_quantity, "order quantity", row.fill_bar),
            None => panic!("the filled order has no quantity"),
        }
    }
}

#[test]
fn no_order_is_pending_after_finish() {
    let bars = load_bars();
    let (_, _, orders) = run(&bars);
    let resolved = last_record_per_order(&orders);

    assert!(!resolved.is_empty());
    for order in &resolved {
        assert_ne!(
            order.state,
            OrderState::Pending,
            "order {} is still pending",
            order.order_id
        );
    }
}

#[test]
fn later_bars_do_not_change_earlier_records() {
    let bars = load_bars();
    let prefix = 3;

    let (prefix_fills, prefix_rejections, prefix_orders) = run(&bars[..prefix]);
    let (full_fills, full_rejections, full_orders) = run(&bars);

    let early_fills = |fills: &[Fill]| -> Vec<Fill> {
        fills
            .iter()
            .copied()
            .filter(|fill| fill.bar < prefix)
            .collect()
    };
    let early_orders = |orders: &[OrderRecord]| -> Vec<OrderRecord> {
        orders
            .iter()
            .copied()
            .filter(|order| effective_bar(order) < prefix)
            .collect()
    };
    let early_rejections = |rejections: &[Rejection]| -> Vec<Rejection> {
        rejections
            .iter()
            .copied()
            .filter(|rejection| rejection.bar < prefix)
            .collect()
    };

    assert_eq!(early_fills(&prefix_fills), early_fills(&full_fills));
    assert_eq!(early_orders(&prefix_orders), early_orders(&full_orders));
    assert_eq!(
        early_rejections(&prefix_rejections),
        early_rejections(&full_rejections)
    );

    let mut changed = bars.to_vec();
    changed[4].candle = Candle::new(4, 3600, 200.0, 200.5, 199.0, 200.0, Some(10.0))
        .expect("the changed candle is valid");
    let (changed_fills, changed_rejections, changed_orders) = run(&changed);
    assert_eq!(early_fills(&changed_fills), early_fills(&full_fills));
    assert_eq!(early_orders(&changed_orders), early_orders(&full_orders));
    assert_eq!(
        early_rejections(&changed_rejections),
        early_rejections(&full_rejections)
    );
}
